  UNIQUE KEY `uq_ad_day` (`Ad_ID`,`Performance_Date`),
  CONSTRAINT `ad_performance_ibfk_1` FOREIGN KEY (`Ad_ID`) REFERENCES `AD` (`Ad_ID`) ON DELETE CASCADE,
  CONSTRAINT `ad_performance_chk_1` CHECK ((`Reach` <= `Impressions`))
) ENGINE=InnoDB AUTO_INCREMENT=8695 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
