DROP TABLE IF EXISTS `MEMBERSHIP`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `MEMBERSHIP` (
  `Membership_ID` int NOT NULL AUTO_INCREMENT,
  `Customer_ID` int NOT NULL,
  `Tier` varchar(10) NOT NULL,
  `Points_Balance` int NOT NULL DEFAULT '0',
  `Annual_Spend` decimal(10,2) NOT NULL DEFAULT '0.00',
  `Points_Preference` varchar(10) NOT NULL,
  `Membership_Start_Date` date NOT NULL,
  PRIMARY KEY (`Membership_ID`),
  UNIQUE KEY `Customer_ID` (`Customer_ID`),
  CONSTRAINT `membership_ibfk_1` FOREIGN KEY (`Customer_ID`) REFERENCES `CUSTOMER` (`Customer_ID`) ON DELETE CASCADE,
  CONSTRAINT `membership_chk_1` CHECK ((`Tier` in (_utf8mb4'Bronze',_utf8mb4'Silver',_utf8mb4'Gold'))),
  CONSTRAINT `membership_chk_2` CHECK ((`Points_Preference` in (_utf8mb4'Rewards',_utf8mb4'Qantas')))
) ENGINE=InnoDB AUTO_INCREMENT=351 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

