--
-- Table structure for table `ORDER`
--

DROP TABLE IF EXISTS `ORDER`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ORDER` (
  `Order_ID` int NOT NULL AUTO_INCREMENT,
  `Customer_ID` int NOT NULL,
  `Session_ID` int DEFAULT NULL,
  `Order_Date` datetime NOT NULL,
  `Order_Total` decimal(10,2) NOT NULL,
  `Discount_Applied` decimal(10,2) NOT NULL DEFAULT '0.00',
  `Channel` varchar(20) NOT NULL,
  PRIMARY KEY (`Order_ID`),
  KEY `Customer_ID` (`Customer_ID`),
  KEY `Session_ID` (`Session_ID`),
  CONSTRAINT `order_ibfk_1` FOREIGN KEY (`Customer_ID`) REFERENCES `CUSTOMER` (`Customer_ID`) ON DELETE CASCADE,
  CONSTRAINT `order_ibfk_2` FOREIGN KEY (`Session_ID`) REFERENCES `SESSION` (`Session_ID`) ON DELETE SET NULL,
  CONSTRAINT `order_chk_1` CHECK ((`Channel` in (_utf8mb4'Online',_utf8mb4'In-store')))
) ENGINE=InnoDB AUTO_INCREMENT=2714 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
