  CONSTRAINT `product_chk_1` CHECK ((`Sale_Price` <= `RRP`)),
  CONSTRAINT `product_chk_2` CHECK ((`Cost_Price` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
