DROP TABLE IF EXISTS `RETURN`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `RETURN` (
  `Return_ID` int NOT NULL AUTO_INCREMENT,
  `Order_ID` int NOT NULL,
  `SKU` varchar(12) NOT NULL,
  `Return_Date` datetime NOT NULL,
  `Quantity_Returned` int NOT NULL,
  `Return_Reason` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`Return_ID`),
  KEY `Order_ID` (`Order_ID`,`SKU`),
  CONSTRAINT `return_ibfk_1` FOREIGN KEY (`Order_ID`, `SKU`) REFERENCES `ORDER_ITEM` (`Order_ID`, `SKU`) ON DELETE CASCADE,
  CONSTRAINT `return_chk_1` CHECK ((`Quantity_Returned` > 0)),
  CONSTRAINT `return_chk_2` CHECK ((`Return_Reason` in (_utf8mb4'Size_Fit',_utf8mb4'Changed_Mind',_utf8mb4'Faulty',_utf8mb4'Not_As_Described',_utf8mb4'Late_Delivery')))
) ENGINE=InnoDB AUTO_INCREMENT=622 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
