DROP TABLE IF EXISTS `SESSION`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `SESSION` (
  `Session_ID` int NOT NULL AUTO_INCREMENT,
  `Click_ID` int NOT NULL,
  `Session_Start` datetime NOT NULL,
  `Session_End` datetime DEFAULT NULL,
  `Pages_Viewed` int NOT NULL DEFAULT '1',
  `Bounced` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`Session_ID`),
  UNIQUE KEY `Click_ID` (`Click_ID`),
  CONSTRAINT `session_ibfk_1` FOREIGN KEY (`Click_ID`) REFERENCES `CLICK` (`Click_ID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12654 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
